query.expression:
max(
    otelcol_exporter_queue_size{
        exporter=~"${exporter:regex}", job="$job"
    , cluster_id=~"${cluster_id:regex}"}
) by (exporter $grouping)
/
min(
    otelcol_exporter_queue_capacity{
        exporter=~"${exporter:regex}", job="$job"
    , cluster_id=~"${cluster_id:regex}"}
) by (exporter $grouping)

